package pl.atrop.powerguard.bcknd.shared.infrastructure.repository.db.sqldb.boundaries;
import jakarta.enterprise.context.ApplicationScoped; import jakarta.persistence.*; import java.util.*; import pl.atrop.powerguard.bcknd.shared.infrastructure.repository.db.sqldb.entities.UsersSites;
@ApplicationScoped public class UsersSitesBoundary extends AbstractFacade<UsersSites>{ @PersistenceContext(unitName="powerguradPU") private EntityManager em; public UsersSitesBoundary(){super(UsersSites.class);} protected EntityManager getEntityManager(){return em;} public Set<Long> findSiteIds(Long userId){if(userId==null)return Set.of();return new LinkedHashSet<>(em.createQuery("SELECT us.siteId FROM UsersSites us WHERE us.userId=:u ORDER BY us.siteId",Long.class).setParameter("u",userId).getResultList());} public void replaceSiteIds(Long userId,Collection<Long> ids){em.createQuery("DELETE FROM UsersSites us WHERE us.userId=:u").setParameter("u",userId).executeUpdate();if(ids!=null)ids.stream().filter(Objects::nonNull).distinct().forEach(id->em.persist(new UsersSites(userId,id)));em.flush();} public void deleteByUserId(Long userId){em.createQuery("DELETE FROM UsersSites us WHERE us.userId=:u").setParameter("u",userId).executeUpdate();em.flush();} }
